#!/usr/bin/env python3
"""Autonomous control plane for the EDARSAHUB universal worker.

This process is intentionally independent from the deterministic job executor.
It repairs recoverable runtime/control-plane failures without routing the repair
through the same job/claim path that may be unhealthy.

Safety invariants:
- never touches Production;
- never force-pushes;
- never destroys local changes (dirty state is stashed before safe FF only);
- Agent Guard orphan claims are quarantined, never deleted;
- live PIDs are always preserved;
- stale processing jobs are requeued only after a conservative grace period.
"""
from __future__ import annotations

import hashlib
import json
import os
import re
import shutil
import signal
import subprocess
import tempfile
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from tools.mirror_sync.worker_slot_runtime import (
    load_slot,
    slot_is_live,
)
from tools.mirror_sync.worker_maintenance_runtime import (
    audit_runtime_incident,
    declare_runtime_incident,
    read_runtime_incident,
    register_repair_attempt,
    register_repair_result,
    repair_attempt_allowed,
    supersede_runtime_incident,
)
from tools.mirror_sync.worker_repair_auto_loop import (
    advance_repair_automation,
)
from tools.mirror_sync import (
    worker_repair_capability_registry as learned_registry,
)

ROOT = Path(os.environ.get("EDARSAHUB_ROOT", "/app"))
GIT = ROOT / ".git"
STATE = GIT / "universal-worker-queue"
RUNTIME = STATE / "runtime"
PROCESSING = STATE / "processing"
PENDING = STATE / "pending"
RESULTS = STATE / "results"
REJECTED = STATE / "rejected"
PUBLISHED = STATE / "published"
AGENT_GUARD = GIT / "agent-guard"
AGENT_QUARANTINE = GIT / "agent-guard-quarantine"
AUDIT = STATE / "control-plane-audit.jsonl"
STATUS = RUNTIME / "control_plane_status.json"
REMOTE = os.environ.get("EDARSAHUB_QUEUE_REMOTE", "origin")
DEV_BRANCH = "Edarsahub_Desarrollo"
INTERVAL = int(os.environ.get("EDARSAHUB_CONTROL_PLANE_INTERVAL", "15"))
HEARTBEAT_STALE = int(os.environ.get("EDARSAHUB_WORKER_HEARTBEAT_STALE_SECONDS", "60"))
CLAIM_GRACE = int(os.environ.get("EDARSAHUB_AGENT_CLAIM_GRACE_SECONDS", "90"))
PROCESSING_GRACE = int(os.environ.get("EDARSAHUB_PROCESSING_REQUEUE_SECONDS", "120"))
OPERATIONAL_PROCESSING_GRACE = int(
    os.environ.get("EDARSAHUB_OPERATIONAL_PROCESSING_REQUEUE_SECONDS", "21600")
)
OPERATIONAL_PROCESSING_MODES = {
    "SOFTRESTAURANT_FULL_HISTORY_RESYNC",
    "MPRO_FULL_HISTORY_RESYNC",
    "ISCAM_DETAIL_BACKFILL",
    "ISCAM_PAYMENTS_ONLY_RESYNC",
    "COMERCIAL_RANGE_RESYNC",
    "COMERCIAL_OPEN_DAY_SYNC",
    "SQL_MIGRATION_DEVELOPMENT",
}
WORKER_SERVICE = os.environ.get("EDARSAHUB_UNIVERSAL_WORKER_SERVICE", "edarsahub-universal-worker")
EXPECTED_GENERATION_RE = re.compile(r'^RUNTIME_GENERATION="([^"]+)"', re.MULTILINE)
PID_RE = re.compile(r'(?i)["\']?pid["\']?\s*[:=]\s*["\']?(\d+)')
WORKER_TOKEN_RE = re.compile(r"(?:worker|queue-publisher)-[A-Za-z0-9._-]{3,160}")

BOOTSTRAP_STATE = Path(
    os.environ.get(
        "EDARSAHUB_BOOTSTRAP_STATE",
        "/var/lib/edarsahub-bootstrap",
    )
)
CONTROL_PLANE_RUNTIME_MARKER = (
    BOOTSTRAP_STATE / "control_plane_active_runtime.json"
)
PLATFORM_MANAGED_SYSTEM_DEPS = ".emergent/system_deps.txt"

def expected_platform_system_deps_drift() -> bool:
    current = ROOT / PLATFORM_MANAGED_SYSTEM_DEPS
    try:
        if not current.is_file() or current.read_bytes() != b"":
            return False
    except OSError:
        return False

    canonical = run(
        ["git", "show", f"HEAD:{PLATFORM_MANAGED_SYSTEM_DEPS}"],
        timeout=20,
    )
    if canonical.returncode != 0 or canonical.stdout.strip() != "git":
        return False

    staged = run(
        [
            "git", "diff", "--cached", "--quiet", "--",
            PLATFORM_MANAGED_SYSTEM_DEPS,
        ],
        timeout=20,
    )
    if staged.returncode != 0:
        return False

    unstaged = run(
        [
            "git", "diff", "--quiet", "--",
            PLATFORM_MANAGED_SYSTEM_DEPS,
        ],
        timeout=20,
    )
    return unstaged.returncode == 1

def effective_git_status() -> str:
    proc = run(
        ["git", "status", "--porcelain=v1", "--untracked-files=all"],
        timeout=20,
    )
    if proc.returncode != 0:
        raise RuntimeError("GIT_STATUS_FAILED")
    lines = proc.stdout.splitlines()
    if expected_platform_system_deps_drift():
        lines = [
            line for line in lines
            if line != " M .emergent/system_deps.txt"
        ]
    return "\n".join(line for line in lines if line.strip())


def _parse_porcelain_dirty_paths(porcelain_text: str) -> set[str]:
    """Extract normalized repo-relative paths from git status --porcelain=v1 output."""
    paths: set[str] = set()
    for raw_line in (porcelain_text or "").splitlines():
        if not raw_line.strip():
            continue
        if len(raw_line) >= 4 and raw_line[2] == " ":
            path_part = raw_line[3:].strip()
        elif len(raw_line) >= 3 and raw_line[1] == " ":
            path_part = raw_line[2:].strip()
        else:
            parts = raw_line.strip().split(None, 1)
            path_part = parts[1].strip() if len(parts) == 2 else ""
        if not path_part:
            continue
        if " -> " in path_part:
            for seg in path_part.split(" -> "):
                norm = seg.strip().strip('"').lstrip("./")
                if norm:
                    paths.add(norm)
        else:
            norm = path_part.strip('"').lstrip("./")
            if norm:
                paths.add(norm)
    return paths


def _dirty_paths_overlap_prefixes(
    dirty_paths: set[str],
    prefixes: tuple[str, ...] | list[str],
) -> bool:
    """Fail-closed check: True if any dirty path equals or lives under any protected prefix."""
    for dp in dirty_paths:
        norm_dp = dp.strip().lstrip("./").rstrip("/")
        if not norm_dp:
            return True
        for pref in prefixes:
            norm_p = pref.strip().lstrip("./").rstrip("/")
            if not norm_p:
                continue
            if norm_dp == norm_p or norm_dp.startswith(norm_p + "/"):
                return True
    return False

CONTROL_PLANE_IDENTITY_PATHS = (
    "tools/mirror_sync/worker_control_plane.py",
    "tools/mirror_sync/worker_maintenance_runtime.py",
    "tools/mirror_sync/worker_maintenance_controller.py",
    "tools/mirror_sync/worker_maintenance_contract.py",
    "tools/mirror_sync/worker_auditor.py",
    "tools/mirror_sync/worker_repair.py",
    "tools/mirror_sync/worker_lifecycle_recovery.py",
    "tools/mirror_sync/worker_cross_domain_handoff.py",
    "tools/mirror_sync/git_divergence_guard.py",
    "tools/mirror_sync/worker_repair_auto_loop.py",
    "tools/mirror_sync/worker_runtime_fingerprint.py",
)

BACKEND_SERVICE = os.environ.get("EDARSAHUB_BACKEND_SERVICE", "backend")
MCP_SERVICE = os.environ.get("EDARSAHUB_MCP_SERVICE", "edarsahub-worker-mcp")
AUTOCONVERGENCE_STATE = RUNTIME / "autoconvergence_state.json"
ACTIVE_MCP_BACKEND_TREE = RUNTIME / "active_mcp_backend_tree_sha"
MCP_BACKEND_IDENTITY_PATHS = (
    "backend/modules/worker_ingress",
    "backend/modules/worker_mcp",
    "tools/mirror_sync/worker_runtime_fingerprint.py",
)
AUTOCONVERGENCE_WORKER_COOLDOWN_SECONDS = int(
    os.environ.get("EDARSAHUB_AUTOCONVERGENCE_WORKER_COOLDOWN_SECONDS", "45")
)
AUTOCONVERGENCE_MCP_BACKEND_COOLDOWN_SECONDS = int(
    os.environ.get("EDARSAHUB_AUTOCONVERGENCE_MCP_BACKEND_COOLDOWN_SECONDS", "90")
)
AUTOCONVERGENCE_MIRROR_COOLDOWN_SECONDS = int(
    os.environ.get("EDARSAHUB_AUTOCONVERGENCE_MIRROR_COOLDOWN_SECONDS", "60")
)


def utc_now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def epoch() -> float:
    return time.time()


def run(args: list[str], timeout: int = 30, check: bool = False) -> subprocess.CompletedProcess[str]:
    result = subprocess.run(
        args,
        cwd=str(ROOT),
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        timeout=timeout,
        check=False,
        env={**os.environ, "GIT_TERMINAL_PROMPT": "0"},
    )
    if check and result.returncode != 0:
        raise RuntimeError(f"COMMAND_FAILED:{args}:{result.stdout[-1500:]}")
    return result


def control_plane_runtime_identity() -> str:
    components: list[str] = []

    for rel in CONTROL_PLANE_IDENTITY_PATHS:
        blob = git_output(
            "rev-parse",
            f"HEAD:{rel}",
        ).strip()

        if not re.fullmatch(r"[0-9a-f]{40}", blob):
            raise RuntimeError(
                f"CONTROL_PLANE_IDENTITY_INVALID:{rel}"
            )

        components.append(f"{rel}={blob}")

    return hashlib.sha256(
        ("\\n".join(components) + "\\n").encode("utf-8")
    ).hexdigest()


def write_control_plane_runtime_marker() -> dict[str, Any]:
    identity = control_plane_runtime_identity()
    development_sha = git_output(
        "rev-parse",
        "HEAD",
    ).strip()

    if not re.fullmatch(
        r"[0-9a-f]{40}",
        development_sha,
    ):
        raise RuntimeError(
            "CONTROL_PLANE_DEVELOPMENT_SHA_INVALID"
        )

    payload = {
        "schema": (
            "edarsahub.control-plane-active-runtime.v1"
        ),
        "active_identity": identity,
        "development_sha": development_sha,
        "pid": os.getpid(),
        "started_at_utc": utc_now(),
        "production_touched": False,
    }

    atomic_json(
        CONTROL_PLANE_RUNTIME_MARKER,
        payload,
    )

    return payload


def audit(event: str, **fields: Any) -> None:
    STATE.mkdir(parents=True, exist_ok=True)
    payload = {"at_utc": utc_now(), "event": event, **fields, "production_touched": False}
    with AUDIT.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(payload, ensure_ascii=False, sort_keys=True) + "\n")


def atomic_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=path.parent, delete=False) as handle:
        json.dump(payload, handle, ensure_ascii=False, indent=2, sort_keys=True)
        handle.write("\n")
        tmp = handle.name
    os.replace(tmp, path)


def read_text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8", errors="replace").strip()
    except OSError:
        return ""


def pid_alive(pid: int) -> bool:
    if pid <= 1:
        return False
    try:
        os.kill(pid, 0)
        return True
    except OSError:
        return False


def parse_iso_age(value: str) -> float | None:
    if not value:
        return None
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
        return max(0.0, epoch() - dt.timestamp())
    except ValueError:
        return None


def expected_generation() -> str:
    script = ROOT / "tools" / "mirror_sync" / "universal_job_worker.sh"
    match = EXPECTED_GENERATION_RE.search(read_text(script))
    return match.group(1) if match else ""


def request_universal_restart(reason: str) -> bool:
    env_name = (
        os.environ.get("EDARSA_ENV")
        or os.environ.get("APP_ENV")
        or os.environ.get("ENVIRONMENT")
        or "PREVIEW"
    ).upper()
    if "PROD" in env_name:
        audit("UNIVERSAL_RESTART_BLOCKED_PRODUCTION_ENV", reason=reason, environment=env_name)
        return False
    result = run(["supervisorctl", "restart", WORKER_SERVICE], timeout=30)
    ok = result.returncode == 0
    audit(
        "UNIVERSAL_RESTART_REQUESTED",
        reason=reason,
        service=WORKER_SERVICE,
        ok=ok,
        output=result.stdout[-1000:],
    )
    return ok


def heal_runtime_generation_and_heartbeat() -> dict[str, Any]:
    expected = expected_generation()
    actual = read_text(RUNTIME / "generation")
    pid_raw = read_text(RUNTIME / "pid")
    pid = int(pid_raw) if pid_raw.isdigit() else 0
    cycle = read_text(RUNTIME / "last_cycle_utc")
    cycle_age = parse_iso_age(cycle)
    receive = read_text(RUNTIME / "last_receive_utc")
    receive_age = parse_iso_age(receive)

    generation_stale = bool(expected and actual != expected)
    # last_receive_utc is transport telemetry, not process liveness. It can
    # remain old while the queue is idle or a bounded receive is in flight.
    # last_cycle_utc is written by the worker before every intake attempt.
    heartbeat_stale = cycle_age is None or cycle_age > HEARTBEAT_STALE
    pid_dead = not pid_alive(pid)

    current_job_id = read_text(
        RUNTIME / "current_job_id"
    ).strip()

    active_job_ownership: dict[str, Any] = {}
    heartbeat_deferred_for_active_job = False

    if heartbeat_stale and current_job_id and not pid_dead:
        active_job_ownership = active_execution_ownership(
            current_job_id,
            heartbeat_stale_seconds=PROCESSING_GRACE,
        )

        if active_job_ownership.get("active") is True:
            heartbeat_stale = False
            heartbeat_deferred_for_active_job = True
            audit(
                "WORKER_HEARTBEAT_STALE_DEFERRED_ACTIVE_JOB",
                job_id=current_job_id,
                ownership=active_job_ownership,
            )

    if generation_stale or heartbeat_stale or pid_dead:
        reason = ",".join(
            name
            for name, active in (
                ("GENERATION_STALE", generation_stale),
                ("HEARTBEAT_STALE", heartbeat_stale),
                ("PID_DEAD", pid_dead),
            )
            if active
        )
        request_universal_restart(reason)

    return {
        "expected_generation": expected,
        "actual_generation": actual,
        "pid": pid,
        "pid_alive": not pid_dead,
        "last_cycle_utc": cycle or None,
        "last_cycle_age_seconds": cycle_age,
        "last_receive_utc": receive or None,
        "last_receive_age_seconds": receive_age,
        "current_job_id": current_job_id or None,
        "active_job_ownership": active_job_ownership,
        "heartbeat_deferred_for_active_job": (
            heartbeat_deferred_for_active_job
        ),
        "runtime_repair_needed": (
            generation_stale
            or heartbeat_stale
            or pid_dead
        ),
    }


def git_output(*args: str) -> str:
    result = run(["git", *args], timeout=45)
    if result.returncode != 0:
        raise RuntimeError(f"GIT_FAILED:{args}:{result.stdout[-1200:]}")
    return result.stdout.strip()


def preserve_and_fast_forward() -> dict[str, Any]:
    """Converge only when remote is a strict FF and local has no unique commits."""
    try:
        run(["git", "fetch", "--quiet", REMOTE, DEV_BRANCH], timeout=60, check=True)
        branch = git_output("branch", "--show-current")
        if branch != DEV_BRANCH:
            return {"ff": "SKIP_WRONG_BRANCH", "branch": branch}
        local = git_output("rev-parse", "HEAD")
        remote = git_output("rev-parse", f"{REMOTE}/{DEV_BRANCH}")
        if local == remote:
            return {"ff": "ALREADY_ALIGNED", "local": local}
        counts = git_output("rev-list", "--left-right", "--count", f"HEAD...{REMOTE}/{DEV_BRANCH}").split()
        local_ahead, remote_ahead = (int(counts[0]), int(counts[1]))
        if local_ahead != 0 or remote_ahead <= 0:
            return {"ff": "SKIP_NON_FF", "local_ahead": local_ahead, "remote_ahead": remote_ahead}

        dirty = effective_git_status()
        stash_ref = None
        dirty_paths: set[str] = set()
        if dirty:
            dirty_paths = _parse_porcelain_dirty_paths(dirty)
            upstream_diff = run(
                ["git", "diff", "--name-only", f"HEAD..{REMOTE}/{DEV_BRANCH}"],
                timeout=30,
            )
            if upstream_diff.returncode != 0 or not dirty_paths:
                audit("FAST_FORWARD_DEFERRED_LOCAL_DIRTY")
                return {"ff": "DEFER_LOCAL_DIRTY"}
            upstream_paths = {
                ln.strip().lstrip("./")
                for ln in (upstream_diff.stdout or "").splitlines()
                if ln.strip()
            }
            conflicts = sorted(dirty_paths & upstream_paths)
            if conflicts or not upstream_paths:
                audit("FAST_FORWARD_DEFERRED_LOCAL_DIRTY", scope_conflicts=conflicts)
                return {"ff": "DEFER_LOCAL_DIRTY", "scope_conflicts": conflicts}

        ff = run(["git", "merge", "--ff-only", f"{REMOTE}/{DEV_BRANCH}"], timeout=60)
        if ff.returncode != 0:
            audit("FAST_FORWARD_FAILED", output=ff.stdout[-1200:], stash=stash_ref)
            return {"ff": "FAILED", "stash": stash_ref}
        new_head = git_output("rev-parse", "HEAD")
        if dirty_paths:
            preserved = sorted(dirty_paths)
            audit(
                "FAST_FORWARD_APPLIED_DISJOINT_DIRTY",
                from_sha=local,
                to_sha=new_head,
                dirty_paths_preserved=preserved,
            )
            return {
                "ff": "APPLIED",
                "from": local,
                "to": new_head,
                "disjoint_dirty_preserved": True,
                "dirty_paths_preserved": preserved,
            }
        audit("FAST_FORWARD_APPLIED", from_sha=local, to_sha=new_head)
        return {"ff": "APPLIED", "from": local, "to": new_head}
    except Exception as exc:
        audit("FAST_FORWARD_EXCEPTION", error=str(exc))
        return {"ff": "ERROR", "error": str(exc)}


def claim_candidates() -> list[Path]:
    if not AGENT_GUARD.is_dir():
        return []
    candidates: list[Path] = []
    for path in AGENT_GUARD.rglob("*"):
        if not path.is_file():
            continue
        lowered = "/".join(part.lower() for part in path.parts)
        if not any(token in lowered for token in ("claim", "claims", "lock", "locks")):
            continue
        try:
            if path.stat().st_size > 2_000_000:
                continue
        except OSError:
            continue
        text = read_text(path)
        if WORKER_TOKEN_RE.search(path.name) or WORKER_TOKEN_RE.search(text):
            candidates.append(path)
    return candidates


def _cleanup_orphan_publisher_worktree_from_claim(claim_text: str) -> dict[str, Any] | None:
    """Safely remove a clean orphan queue-publisher worktree when its claim is quarantined."""
    try:
        claim_data = json.loads(claim_text)
    except Exception:
        return None
    if not isinstance(claim_data, dict):
        return None
    agent_id = str(claim_data.get("agent_id") or "").strip()
    if not agent_id.startswith("queue-publisher-"):
        return None
    wt_raw = str(claim_data.get("worktree") or "").strip()
    branch = str(claim_data.get("branch") or "").strip()
    outcome: dict[str, Any] = {"agent_id": agent_id, "worktree_removed": False, "branch_removed": False}
    if wt_raw:
        wt_path = Path(wt_raw)
        expected_root = (GIT / "agent-worktrees").resolve()
        try:
            resolved_wt = wt_path.resolve()
        except OSError:
            resolved_wt = wt_path
        if resolved_wt.is_dir() and expected_root in resolved_wt.parents:
            dirty_proc = subprocess.run(
                ["git", "-C", str(resolved_wt), "status", "--porcelain=v1", "--untracked-files=all"],
                text=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                timeout=20,
                check=False,
                env={**os.environ, "GIT_TERMINAL_PROMPT": "0"},
            )
            if dirty_proc.returncode == 0 and not (dirty_proc.stdout or "").strip():
                rem = run(["git", "worktree", "remove", str(resolved_wt)], timeout=30)
                outcome["worktree_removed"] = rem.returncode == 0
                if rem.returncode == 0 and branch.startswith("agent/queue-publisher/"):
                    del_br = run(["git", "branch", "-D", branch], timeout=20)
                    outcome["branch_removed"] = del_br.returncode == 0
            else:
                outcome["dirty_preserved"] = True
    return outcome


def reconcile_agent_guard_orphans() -> dict[str, int]:
    live = recent = quarantined = publisher_worktrees_cleaned = 0
    now_ts = epoch()
    for path in claim_candidates():
        try:
            age = now_ts - path.stat().st_mtime
        except OSError:
            continue
        text = read_text(path)
        try:
            parsed_claim = json.loads(text) if text.startswith("{") else {}
        except Exception:
            parsed_claim = {}
        if isinstance(parsed_claim, dict) and str(parsed_claim.get("status") or "").strip().upper() == "RELEASED":
            continue
        pids = {int(value) for value in PID_RE.findall(text)}
        if any(pid_alive(pid) for pid in pids):
            live += 1
            continue
        if age < CLAIM_GRACE:
            recent += 1
            continue
        try:
            rel = path.relative_to(AGENT_GUARD)
            stamp = datetime.now(timezone.utc).strftime("%Y%m%d")
            destination = AGENT_QUARANTINE / stamp / rel
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(path), str(destination))
            quarantined += 1
            wt_cleanup = _cleanup_orphan_publisher_worktree_from_claim(text)
            if isinstance(wt_cleanup, dict) and wt_cleanup.get("worktree_removed"):
                publisher_worktrees_cleaned += 1
            audit(
                "AGENT_GUARD_ORPHAN_QUARANTINED",
                source=str(path),
                destination=str(destination),
                age_seconds=int(age),
                pids=sorted(pids),
                publisher_worktree_cleanup=wt_cleanup,
            )
        except Exception as exc:
            audit("AGENT_GUARD_QUARANTINE_FAILED", source=str(path), error=str(exc))
    return {
        "live": live,
        "recent": recent,
        "quarantined": quarantined,
        "publisher_worktrees_cleaned": publisher_worktrees_cleaned,
    }


def active_execution_ownership(
    job_id: str,
    *,
    heartbeat_stale_seconds: int,
) -> dict[str, Any]:
    """Return only fresh/live canonical ownership evidence for one job."""
    evidence: dict[str, Any] = {
        "active": False,
        "job_id": job_id,
        "sources": [],
    }

    reconciler_path = RUNTIME / "reconciler.json"
    try:
        reconciler = json.loads(
            reconciler_path.read_text(encoding="utf-8")
        )
    except Exception:
        reconciler = {}

    generated_at = str(
        reconciler.get("generated_at_utc") or ""
    ).strip()
    reconciler_age = parse_iso_age(generated_at)
    reconciler_fresh = (
        reconciler_age is not None
        and reconciler_age <= heartbeat_stale_seconds
    )

    if reconciler_fresh:
        for claim in reconciler.get("claims") or []:
            if not isinstance(claim, dict):
                continue
            if str(claim.get("task_id") or "").strip() != job_id:
                continue
            decision = str(claim.get("decision") or "").strip()
            released = claim.get("released") is True
            if not released and decision in {
                "CLAIM_NOT_STALE",
                "LIVE_PROCESS_REFERENCES_WORKTREE",
                "WORK_NOT_TERMINAL_OR_INTEGRATED",
            }:
                evidence["active"] = True
                evidence["sources"].append(
                    {
                        "kind": "agent_claim",
                        "decision": decision,
                        "reconciler_age_seconds": int(reconciler_age),
                    }
                )

    try:
        slot = load_slot("mutation-1")
    except Exception as exc:
        evidence["slot_error"] = type(exc).__name__
        slot = None

    if (
        isinstance(slot, dict)
        and str(slot.get("job_id") or "").strip() == job_id
    ):
        try:
            live_slot = slot_is_live(
                slot,
                heartbeat_stale_seconds=heartbeat_stale_seconds,
            )
        except Exception as exc:
            evidence["slot_error"] = type(exc).__name__
            live_slot = False

        if live_slot:
            evidence["active"] = True
            evidence["sources"].append(
                {
                    "kind": "slot",
                    "slot_id": slot.get("slot_id"),
                    "state": slot.get("state"),
                }
            )

    writer_owner = STATE / "git-writer.lock.d" / "owner.json"
    try:
        writer = json.loads(
            writer_owner.read_text(encoding="utf-8")
        )
    except Exception:
        writer = {}

    if str(writer.get("job_id") or "").strip() == job_id:
        owner_pid = int(writer.get("owner_pid") or 0)
        owner_alive = pid_alive(owner_pid) if owner_pid > 0 else False
        if owner_alive:
            evidence["active"] = True
            evidence["sources"].append(
                {
                    "kind": "git_writer_lock",
                    "owner_pid": owner_pid,
                    "owner_pid_alive": True,
                }
            )

    return evidence


def requeue_stale_processing() -> int:
    PENDING.mkdir(parents=True, exist_ok=True)
    PROCESSING.mkdir(parents=True, exist_ok=True)
    REJECTED.mkdir(parents=True, exist_ok=True)
    RESULTS.mkdir(parents=True, exist_ok=True)
    requeued = 0
    for path in PROCESSING.glob("*.json"):
        try:
            age = epoch() - path.stat().st_mtime
        except OSError:
            continue
        try:
            envelope = json.loads(path.read_text(encoding="utf-8"))
        except Exception as exc:
            audit("STALE_PROCESSING_INVALID_ENVELOPE", job_file=path.name, error=str(exc))
            continue

        job = envelope.get("job") if isinstance(envelope.get("job"), dict) else {}
        mode = str(job.get("mode") or "").upper().strip()
        processing_grace = (
            OPERATIONAL_PROCESSING_GRACE
            if mode in OPERATIONAL_PROCESSING_MODES
            else PROCESSING_GRACE
        )

        if age < processing_grace:
            continue

        ownership = active_execution_ownership(
            str(job.get("job_id") or path.stem),
            heartbeat_stale_seconds=processing_grace,
        )
        if ownership.get("active") is True:
            audit(
                "STALE_PROCESSING_DEFERRED_ACTIVE_OWNERSHIP",
                job_file=path.name,
                age_seconds=int(age),
                ownership=ownership,
            )
            continue

        retry_count = int(envelope.get("_worker_stale_requeue_count") or 0)
        if retry_count >= 1:
            job = envelope.get("job") if isinstance(envelope.get("job"), dict) else {}
            job_id = str(job.get("job_id") or path.stem)
            completed = utc_now()
            result = {
                "schema": "edarsahub.worker-result.v2",
                "job_id": job_id,
                "status": "BLOCKED",
                "quality_gate": "FAIL",
                "certification": "NOT_CERTIFIED",
                "percent_complete": 0,
                "production_touched": False,
                "blockers": ["processing_stale_after_single_requeue"],
                "completed_at_utc": completed,
                "summary_es": "El job excedio el SLA de processing despues de un unico reintento seguro y fue cerrado terminalmente para no bloquear la cola."
            }
            atomic_json(RESULTS / path.name, result)
            os.replace(path, REJECTED / path.name)
            (RUNTIME / "last_terminal_utc").write_text(completed + "\n", encoding="utf-8")
            audit("STALE_PROCESSING_TERMINATED", job_file=path.name, age_seconds=int(age))
            continue
        target = PENDING / path.name
        if target.exists():
            continue
        envelope["_worker_stale_requeue_count"] = retry_count + 1
        atomic_json(path, envelope)
        os.replace(path, target)
        requeued += 1
        audit("STALE_PROCESSING_REQUEUED", job_file=path.name, age_seconds=int(age), retry_count=retry_count + 1)
    return requeued




GIT_LOCK_BUSY_REPAIR_PATHS = (
    "tools/mirror_sync/git_divergence_guard.py",
    "tools/mirror_sync/universal_job_dispatcher.py",
)

AUTOMATION_STATE_SCHEMA = "edarsahub.worker-repair-automation-state.v1"


def _parse_canonical_utc(value: Any) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None

    try:
        parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        return None

    if parsed.tzinfo is None:
        return None

    return parsed.astimezone(timezone.utc)


def repair_automation_state_path() -> Path:
    return (
        ROOT
        / ".git"
        / "universal-worker-queue"
        / "maintenance"
        / "automation_state.json"
    )


def load_repair_automation_state() -> dict[str, Any]:
    path = repair_automation_state_path()

    fail_closed = {
        "schema": AUTOMATION_STATE_SCHEMA,
        "enabled": False,
        "enabled_at_utc": None,
        "enabled_from_development_sha": None,
        "adopted_job_ids": [],
        "production_allowed": False,
        "valid": False,
    }

    if not path.is_file():
        return fail_closed

    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return fail_closed

    if not isinstance(payload, dict):
        return fail_closed

    enabled_at = _parse_canonical_utc(payload.get("enabled_at_utc"))
    development_sha = str(
        payload.get("enabled_from_development_sha") or ""
    ).strip()

    adopted = payload.get("adopted_job_ids")

    valid = (
        payload.get("schema") == AUTOMATION_STATE_SCHEMA
        and payload.get("enabled") is True
        and payload.get("production_allowed") is False
        and enabled_at is not None
        and bool(re.fullmatch(r"[0-9a-f]{40}", development_sha))
        and isinstance(adopted, list)
        and all(
            isinstance(job_id, str) and job_id.strip()
            for job_id in adopted
        )
    )

    if not valid:
        return fail_closed

    return {
        "schema": AUTOMATION_STATE_SCHEMA,
        "enabled": True,
        "enabled_at_utc": enabled_at.isoformat().replace("+00:00", "Z"),
        "enabled_from_development_sha": development_sha,
        "adopted_job_ids": sorted(set(adopted)),
        "production_allowed": False,
        "valid": True,
    }


def automatic_repair_result_is_eligible(
    result: dict[str, Any],
    automation_state: dict[str, Any],
) -> tuple[bool, str]:
    if not isinstance(result, dict):
        return False, "RESULT_INVALID"

    if automation_state.get("valid") is not True:
        return False, "AUTOMATION_STATE_INVALID"

    if automation_state.get("enabled") is not True:
        return False, "AUTOMATION_DISABLED"

    if automation_state.get("production_allowed") is not False:
        return False, "AUTOMATION_PRODUCTION_POLICY_INVALID"

    if result.get("production_touched") is not False:
        return False, "PRODUCTION_TOUCHED"

    job_id = str(result.get("job_id") or "").strip()

    adopted = set(automation_state.get("adopted_job_ids") or [])

    if job_id and job_id in adopted:
        return True, "EXPLICITLY_ADOPTED"

    completed_at = _parse_canonical_utc(result.get("completed_at_utc"))
    enabled_at = _parse_canonical_utc(
        automation_state.get("enabled_at_utc")
    )

    if completed_at is None:
        return False, "RESULT_COMPLETED_AT_INVALID"

    if enabled_at is None:
        return False, "AUTOMATION_ENABLED_AT_INVALID"

    if completed_at <= enabled_at:
        return False, "HISTORICAL_RESULT"

    return True, "POST_ACTIVATION_RESULT"



def _valid_git_sha(value: Any) -> str | None:
    text = str(value or "").strip().lower()

    if re.fullmatch(r"[0-9a-f]{40}", text):
        return text

    return None


def automatic_repair_source_anchor(
    source_result: dict[str, Any],
) -> tuple[str | None, str]:
    for field in (
        "execution_base_sha",
        "base_sha",
        "initial_base_sha",
        "remote_at_start",
        "local_at_start",
        "candidate_sha",
    ):
        value = _valid_git_sha(
            source_result.get(field)
        )

        if value is not None:
            return value, field

    source_job_id = str(
        source_result.get("job_id") or ""
    ).strip()

    if source_job_id:
        queue_root = (
            ROOT / ".git" / "universal-worker-queue"
        )
        envelope_paths: list[Path] = [
            queue_root / folder / f"{source_job_id}.json"
            for folder in (
                "done",
                "rejected",
                "processing",
                "pending",
                "drafts",
            )
        ]
        rejected_history = (
            queue_root / "rejected_history"
        )
        if rejected_history.is_dir():
            envelope_paths.extend(
                sorted(
                    rejected_history.glob(
                        f"{source_job_id}*.json"
                    )
                )
            )
        for envelope_path in envelope_paths:
            if not envelope_path.is_file():
                continue
            try:
                envelope = json.loads(
                    envelope_path.read_text(
                        encoding="utf-8"
                    )
                )
            except Exception:
                continue
            if not isinstance(envelope, dict):
                continue
            embedded = (
                envelope.get("job")
                if isinstance(
                    envelope.get("job"),
                    dict,
                )
                else envelope
            )
            if not isinstance(embedded, dict):
                continue
            envelope_sha = _valid_git_sha(
                embedded.get("base_sha")
            )
            if envelope_sha is not None:
                return (
                    envelope_sha,
                    "job_envelope_base_sha",
                )

    return None, "SOURCE_ANCHOR_UNAVAILABLE"


def automatic_repair_result_commit(
    result: dict[str, Any],
) -> str | None:
    return (
        _valid_git_sha(result.get("development_sha"))
        or _valid_git_sha(result.get("candidate_sha"))
    )


def automatic_repair_result_is_certified_successor(
    result: dict[str, Any],
) -> bool:
    blockers = result.get("blockers")

    return (
        result.get("status") == "INTEGRATED"
        and result.get("quality_gate") == "PASS"
        and result.get("tests") == "PASS"
        and result.get("git_sync_status")
        == "CERTIFIED_GIT_SYNC"
        and result.get("production_touched") is False
        and blockers in (None, [])
        and automatic_repair_result_commit(result)
        is not None
    )


def _git_is_ancestor(
    ancestor_sha: str,
    descendant_sha: str,
) -> bool:
    proc = subprocess.run(
        [
            "git",
            "merge-base",
            "--is-ancestor",
            ancestor_sha,
            descendant_sha,
        ],
        cwd=str(ROOT),
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    return proc.returncode == 0


def _target_diff_paths(
    base_sha: str,
    head_sha: str,
    target_paths: tuple[str, ...],
) -> set[str] | None:
    try:
        return {
            line.strip()
            for line in git_output(
                "diff",
                "--name-only",
                base_sha,
                head_sha,
                "--",
                *target_paths,
            ).splitlines()
            if line.strip()
        }
    except Exception:
        return None


def find_certified_successor_result(
    source_result: dict[str, Any],
    target_paths: tuple[str, ...],
    result_corpus: tuple[dict[str, Any], ...],
    *,
    current_head: str,
) -> dict[str, Any] | None:
    source_anchor, _anchor_field = (
        automatic_repair_source_anchor(
            source_result
        )
    )

    source_status = str(
        source_result.get("status") or ""
    ).strip()
    preworktree_failure = source_status in {
        "GIT_LOCK_BUSY",
        "GIT_WORKTREE_NOT_CLEAN",
    }

    if source_anchor is None and not preworktree_failure:
        return None

    if not _valid_git_sha(current_head):
        return None

    source_job_id = str(
        source_result.get("job_id") or ""
    ).strip()

    source_completed = _parse_canonical_utc(
        source_result.get("completed_at_utc")
    )

    if source_anchor is None and source_completed is None:
        return None

    required_paths = set(target_paths)

    if not required_paths:
        return None

    preliminary: list[
        tuple[datetime, str, dict[str, Any]]
    ] = []

    for candidate in result_corpus:
        if candidate is source_result:
            continue

        candidate_job_id = str(
            candidate.get("job_id") or ""
        ).strip()

        if (
            source_job_id
            and candidate_job_id == source_job_id
        ):
            continue

        if not automatic_repair_result_is_certified_successor(
            candidate
        ):
            continue

        successor_sha = (
            automatic_repair_result_commit(candidate)
        )

        if successor_sha is None:
            continue

        candidate_completed = _parse_canonical_utc(
            candidate.get("completed_at_utc")
        )

        if source_anchor is None:
            if (
                candidate_completed is None
                or candidate_completed <= source_completed
            ):
                continue
        elif (
            source_completed is not None
            and candidate_completed is not None
            and candidate_completed <= source_completed
        ):
            continue

        candidate_paths_raw = (
            candidate.get("files_changed") or []
        )

        if not isinstance(candidate_paths_raw, list):
            continue

        candidate_paths = {
            str(path).strip()
            for path in candidate_paths_raw
            if isinstance(path, str)
            and str(path).strip()
        }

        if not required_paths.issubset(
            candidate_paths
        ):
            continue

        sort_time = (
            candidate_completed
            or datetime.min.replace(
                tzinfo=timezone.utc
            )
        )

        preliminary.append(
            (
                sort_time,
                successor_sha,
                candidate,
            )
        )

    if not preliminary:
        return None

    preliminary.sort(
        key=lambda item: (
            item[0],
            item[1],
            str(
                item[2].get("job_id") or ""
            ),
        )
    )

    for _sort_time, successor_sha, candidate in preliminary:
        anchor_to_verify = (
            source_anchor
            or _valid_git_sha(
                candidate.get("execution_base_sha")
            )
            or _valid_git_sha(
                candidate.get("base_sha")
            )
        )

        if anchor_to_verify is None:
            continue

        if not _git_is_ancestor(
            anchor_to_verify,
            successor_sha,
        ):
            continue

        if not _git_is_ancestor(
            successor_sha,
            current_head,
        ):
            continue

        changed = _target_diff_paths(
            anchor_to_verify,
            successor_sha,
            target_paths,
        )

        if changed is None:
            continue

        if not required_paths.issubset(changed):
            continue

        return candidate

    return None


def repair_incident_is_superseded(
    source_result: dict[str, Any],
    target_paths: tuple[str, ...],
    *,
    result_corpus: tuple[dict[str, Any], ...] = (),
) -> tuple[bool, str]:
    development_sha = _valid_git_sha(
        source_result.get("development_sha")
    )

    try:
        current_head = git_output(
            "rev-parse",
            "HEAD",
        ).strip()
    except Exception:
        return False, "CURRENT_HEAD_UNAVAILABLE"

    if not _valid_git_sha(current_head):
        return False, "CURRENT_HEAD_INVALID"

    if development_sha is not None:
        if development_sha == current_head:
            return False, "SOURCE_IS_CURRENT_HEAD"

        if not _git_is_ancestor(
            development_sha,
            current_head,
        ):
            return False, "SOURCE_NOT_ANCESTOR"

        changed_after = _target_diff_paths(
            development_sha,
            current_head,
            target_paths,
        )

        if changed_after is None:
            return False, "TARGET_DIFF_UNAVAILABLE"

        if not changed_after:
            return False, "TARGETS_UNCHANGED"

        if not set(target_paths).issubset(
            changed_after
        ):
            return (
                False,
                "NOT_ALL_TARGETS_SUPERSEDED",
            )

        return True, "SUPERSEDED_BY_CURRENT_HEAD"

    successor = find_certified_successor_result(
        source_result,
        target_paths,
        result_corpus,
        current_head=current_head,
    )

    if successor is None:
        anchor, anchor_reason = (
            automatic_repair_source_anchor(
                source_result
            )
        )

        if anchor is None:
            return False, anchor_reason

        return (
            False,
            "CERTIFIED_SUCCESSOR_NOT_FOUND",
        )

    return True, "CERTIFIED_SUCCESSOR_RESULT"


def _resolve_automatic_repair_candidate_scope(
    result: dict[str, Any],
    *,
    fallback_job_id: str,
    automation_state: dict[str, Any],
    repairable_statuses: set[str],
    worker_roots: tuple[str, ...],
    git_lock_busy_repair_paths: tuple[str, ...] = GIT_LOCK_BUSY_REPAIR_PATHS,
) -> dict[str, Any] | None:
    status = str(result.get("status") or "").strip()
    certification = str(
        result.get("certification") or ""
    ).strip()

    if status not in repairable_statuses:
        return None

    if certification not in {
        "",
        "NOT_CERTIFIED",
        "PENDING_AUDIT_EVIDENCE",
    }:
        return None

    if result.get("production_touched") is not False:
        return None

    boundary_allowed, boundary_reason = (
        automatic_repair_result_is_eligible(
            result,
            automation_state,
        )
    )

    source_job_id = str(
        result.get("job_id") or fallback_job_id
    ).strip()
    if not source_job_id:
        return None

    blockers = {
        str(value or "").strip().upper()
        for value in result.get("blockers") or []
        if str(value or "").strip()
    }

    learned_matches = []

    if blockers:
        for capability in (
            learned_registry.iter_learned_capabilities()
        ):
            if not capability.reusable:
                continue
            blocker_signature = str(
                (capability.evidence or {}).get(
                    "blocker_signature"
                )
                or ""
            ).strip().upper()

            if (
                blocker_signature
                and blocker_signature in blockers
            ):
                learned_matches.append(capability)

        learned_matches = (
            learned_registry._filter_superseded_capabilities(
                learned_matches
            )
        )

    if len(learned_matches) > 1:
        return {
            "ambiguous": True,
            "source_job_id": source_job_id,
            "status": status,
            "boundary_allowed": boundary_allowed,
            "boundary_reason": boundary_reason,
        }

    learned_capability = (
        learned_matches[0]
        if len(learned_matches) == 1
        else None
    )

    if learned_capability is not None:
        raw_paths = list(
            learned_capability.required_paths
        )
    else:
        raw_paths = (
            result.get("files_changed")
            or result.get("expected_scope")
            or []
        )

    if status == "GIT_LOCK_BUSY" and not raw_paths:
        raw_paths = list(
            git_lock_busy_repair_paths
        )

    if not isinstance(raw_paths, list):
        return None

    normalized = {
        str(path).strip()
        for path in raw_paths
        if isinstance(path, str)
        and str(path).strip()
    }

    target_paths = tuple(
        sorted(
            path
            for path in normalized
            if any(
                path.startswith(root)
                for root in worker_roots
            )
        )
    )

    if not target_paths:
        return None

    # Scope derivado de capability conocida o resultado debe ser
    # exclusivamente infraestructura Worker.
    if len(target_paths) != len(normalized):
        return None

    digest = hashlib.sha256(
        (
            source_job_id
            + "\n"
            + status
            + "\n"
            + "\n".join(target_paths)
        ).encode("utf-8")
    ).hexdigest()[:20]

    return {
        "ambiguous": False,
        "source_job_id": source_job_id,
        "status": status,
        "boundary_allowed": boundary_allowed,
        "boundary_reason": boundary_reason,
        "target_paths": target_paths,
        "incident_id": f"WORKER-{digest}",
        "learned_capability": learned_capability,
        "normalized_blockers": tuple(sorted(blockers)),
    }


def select_automatic_repair_candidates(
    results: tuple[dict[str, Any], ...],
    automation_state: dict[str, Any],
    repairable_statuses: set[str],
    worker_roots: tuple[str, ...],
    *,
    fallback_job_ids: tuple[str, ...] = (),
) -> tuple[dict[str, dict[str, Any]], int]:
    """Select one canonical repair incident per active root cause."""
    groups: dict[tuple[Any, ...], list[dict[str, Any]]] = {}

    for index, result in enumerate(results):
        fallback_job_id = (
            fallback_job_ids[index]
            if index < len(fallback_job_ids)
            else ""
        )
        resolved = _resolve_automatic_repair_candidate_scope(
            result,
            fallback_job_id=fallback_job_id,
            automation_state=automation_state,
            repairable_statuses=repairable_statuses,
            worker_roots=worker_roots,
        )
        if resolved is None or resolved["ambiguous"]:
            continue

        if not resolved["boundary_allowed"]:
            continue

        source_job_id = resolved["source_job_id"]
        status = resolved["status"]
        target_paths = resolved["target_paths"]
        incident_id = resolved["incident_id"]
        learned_capability = resolved["learned_capability"]

        existing = read_runtime_incident(incident_id)
        if existing is not None and existing.state in {
            "SUPERSEDED",
            "CERTIFIED",
        }:
            continue

        candidate_superseded, _ = repair_incident_is_superseded(
            result,
            target_paths,
            result_corpus=results,
        )
        if candidate_superseded:
            continue

        if existing is None:
            has_binding = False
            attempts = 0
            owns_attempt_history = False
            attempt_allowed = True
        else:
            has_binding = bool(existing.repair_job_id)
            attempts = int(existing.attempts or 0)
            owns_attempt_history = bool(
                attempts > 0
                or existing.cooldown_until_epoch is not None
                or existing.state == "REPAIRED_PENDING_AUDIT"
            )
            attempt_allowed, _ = repair_attempt_allowed(
                incident_id
            )

        completed = _parse_canonical_utc(
            result.get("completed_at_utc")
        ) or datetime.min.replace(tzinfo=timezone.utc)

        cause_discriminator = (
            ("CAPABILITY", learned_capability.code)
            if learned_capability is not None
            else ("BLOCKERS", resolved["normalized_blockers"])
        )
        cause_key = (
            status,
            cause_discriminator,
            target_paths,
        )

        groups.setdefault(cause_key, []).append(
            {
                "source_job_id": source_job_id,
                "incident_id": incident_id,
                # Active repair binding and attempt-history/cooldown/max-attempts
                # ownership always take precedence over raw recency.
                "priority": (
                    has_binding,
                    owns_attempt_history,
                    attempts,
                    attempt_allowed,
                    completed,
                    source_job_id,
                ),
            }
        )

    selections: dict[str, dict[str, Any]] = {}
    for candidates in groups.values():
        selected = max(
            candidates,
            key=lambda item: item["priority"],
        )
        for candidate in candidates:
            selections[candidate["incident_id"]] = selected

    return selections, len(groups)


def automatic_repair_orchestration() -> dict[str, Any]:
    """Detect bounded Worker-infrastructure repair incidents only.

    Detection and incident declaration occur here.
    Mutation execution remains exclusively in Universal Worker.
    Independent certification remains exclusively in Worker Auditor.
    """
    results_root = ROOT / ".git" / "universal-worker-queue" / "results"
    automation_state = load_repair_automation_state()

    observed = 0
    eligible = 0
    declared = 0
    blocked = 0
    incidents: list[dict[str, Any]] = []

    repairable_statuses = {
        "GIT_LOCK_BUSY",
        "GIT_TESTS_FAILED",
        "GIT_SCOPE_VIOLATION",
        "GIT_DIVERGENCE_BLOCKED",
        "GIT_PUSH_FAILED",
        "BLOCKED",
    }

    worker_roots = (
        "tools/mirror_sync/",
        "backend/modules/worker_runtime_wake/",
        "backend/tests/test_worker_",
        ".github/workflows/universal-worker-",
        ".github/workflows/worker-",
    )

    if not results_root.is_dir():
        return {
            "schema": "edarsahub.worker-automatic-repair.v1",
            "observed_terminal_results": 0,
            "eligible_incidents": 0,
            "declared_incidents": 0,
            "blocked_incidents": 0,
            "selected_incidents": 0,
            "incidents": [],
            "production_touched": False,
        }

    result_corpus: list[dict[str, Any]] = []
    result_stems: list[str] = []

    for result_path in sorted(results_root.glob("*.json")):
        try:
            result = json.loads(
                result_path.read_text(encoding="utf-8")
            )
        except Exception:
            continue

        if not isinstance(result, dict):
            continue

        result_corpus.append(result)
        result_stems.append(result_path.stem)

    result_corpus_tuple = tuple(result_corpus)
    result_stems_tuple = tuple(result_stems)
    root_cause_selections, selected_incident_count = (
        select_automatic_repair_candidates(
            result_corpus_tuple,
            automation_state,
            repairable_statuses,
            worker_roots,
            fallback_job_ids=result_stems_tuple,
        )
    )

    for index, result in enumerate(result_corpus_tuple):
        observed += 1

        if result.get("production_touched") is not False:
            continue

        resolved = _resolve_automatic_repair_candidate_scope(
            result,
            fallback_job_id=result_stems_tuple[index],
            automation_state=automation_state,
            repairable_statuses=repairable_statuses,
            worker_roots=worker_roots,
            git_lock_busy_repair_paths=GIT_LOCK_BUSY_REPAIR_PATHS,
        )
        if resolved is None:
            continue

        source_job_id = resolved["source_job_id"]
        status = resolved["status"]
        boundary_allowed = resolved["boundary_allowed"]
        boundary_reason = resolved["boundary_reason"]

        if resolved["ambiguous"]:
            if not boundary_allowed:
                incidents.append(
                    {
                        "incident_id": None,
                        "source_job_id": source_job_id,
                        "source_status": status,
                        "state": "OBSERVED_NOT_ELIGIBLE",
                        "target_paths": [],
                        "repair_allowed": False,
                        "repair_reason": boundary_reason,
                        "publication_required": False,
                    }
                )
                continue

            blocked += 1
            incidents.append(
                {
                    "incident_id": None,
                    "source_job_id": source_job_id,
                    "source_status": status,
                    "state": "BLOCKED",
                    "target_paths": [],
                    "repair_allowed": False,
                    "repair_reason": (
                        "KNOWN_BLOCKER_CAPABILITY_AMBIGUOUS"
                    ),
                    "publication_required": False,
                }
            )
            continue

        learned_capability = resolved["learned_capability"]
        target_paths = resolved["target_paths"]

        if not boundary_allowed:
            incidents.append(
                {
                    "incident_id": None,
                    "source_job_id": source_job_id,
                    "source_status": status,
                    "state": "OBSERVED_NOT_ELIGIBLE",
                    "target_paths": list(target_paths),
                    "repair_allowed": False,
                    "repair_reason": boundary_reason,
                    "publication_required": False,
                }
            )
            continue

        eligible += 1

        digest = hashlib.sha256(
            (
                source_job_id
                + "\n"
                + status
                + "\n"
                + "\n".join(target_paths)
            ).encode("utf-8")
        ).hexdigest()[:20]

        incident_id = f"WORKER-{digest}"

        blocker_sig = (
            str(
                (learned_capability.evidence or {}).get(
                    "blocker_signature"
                )
                or ""
            ).strip()
            if learned_capability is not None
            else ""
        )

        root_cause_selection = root_cause_selections.get(
            incident_id
        )
        if (
            root_cause_selection is not None
            and root_cause_selection["incident_id"]
            != incident_id
        ):
            incidents.append(
                {
                    "incident_id": incident_id,
                    "source_job_id": source_job_id,
                    "source_status": status,
                    "state": "DUPLICATE_ROOT_CAUSE_SUPPRESSED",
                    "target_paths": list(target_paths),
                    "repair_allowed": False,
                    "repair_reason": (
                        "DUPLICATE_ROOT_CAUSE_SUPPRESSED"
                    ),
                    "selected_incident_id": (
                        root_cause_selection["incident_id"]
                    ),
                    "publication_required": False,
                    "capability_code": (
                        learned_capability.code
                        if learned_capability is not None
                        else None
                    ),
                    "problem_signature": (
                        learned_capability.problem_signature
                        if learned_capability is not None
                        else None
                    ),
                    "blocker_signature": blocker_sig or None,
                }
            )
            continue

        try:
            incident = declare_runtime_incident(
                incident_id,
                list(target_paths),
            )
        except ValueError as exc:
            blocked += 1

            incidents.append(
                {
                    "incident_id": incident_id,
                    "source_job_id": source_job_id,
                    "state": "BLOCKED",
                    "reason": str(exc),
                    "target_paths": list(target_paths),
                }
            )
            continue

        # SUPERSEDED is a terminal, non-actionable maintenance
        # state. Re-observing the same historical failure must
        # never attempt SUPERSEDED -> SUPERSEDED.
        if incident.state == "SUPERSEDED":
            incidents.append(
                {
                    "incident_id": incident.incident_id,
                    "source_job_id": source_job_id,
                    "source_status": status,
                    "state": incident.state,
                    "target_paths": list(target_paths),
                    "repair_allowed": False,
                    "repair_reason": "ALREADY_SUPERSEDED",
                    "publication_required": False,
                }
            )
            continue

        superseded, superseded_reason = (
            repair_incident_is_superseded(
                result,
                target_paths,
                result_corpus=result_corpus_tuple,
            )
        )

        if superseded:
            incident = supersede_runtime_incident(
                incident_id,
                reason=superseded_reason,
            )

            incidents.append(
                {
                    "incident_id": incident.incident_id,
                    "source_job_id": source_job_id,
                    "source_status": status,
                    "state": incident.state,
                    "target_paths": list(target_paths),
                    "repair_allowed": False,
                    "repair_reason": superseded_reason,
                    "publication_required": False,
                }
            )
            continue

        allowed, reason = repair_attempt_allowed(
            incident_id
        )

        incidents.append(
            {
                "incident_id": incident.incident_id,
                "source_job_id": source_job_id,
                "source_status": status,
                "state": incident.state,
                "target_paths": list(target_paths),
                "repair_allowed": allowed,
                "repair_reason": reason,
                "publication_required": allowed,
                "capability_code": (
                    learned_capability.code
                    if learned_capability is not None
                    else None
                ),
                "problem_signature": (
                    learned_capability.problem_signature
                    if learned_capability is not None
                    else None
                ),
                "blocker_signature": blocker_sig or None,
            }
        )

        if allowed:
            declared += 1
        else:
            blocked += 1

    return {
        "schema": "edarsahub.worker-automatic-repair.v1",
        "observed_terminal_results": observed,
        "eligible_incidents": eligible,
        "declared_incidents": declared,
        "blocked_incidents": blocked,
        "selected_incidents": selected_incident_count,
        "incidents": incidents,
        "production_touched": False,
    }


def maintenance_runtime_summary() -> dict[str, Any]:
    """Read-only maintenance-plane visibility for the canonical control plane."""
    maintenance_root = ROOT / ".git" / "universal-worker-queue" / "maintenance" / "incidents"

    incidents: list[dict[str, Any]] = []

    if maintenance_root.is_dir():
        for path in sorted(maintenance_root.glob("*.json")):
            try:
                incident = read_runtime_incident(path.stem)
            except Exception as exc:
                incidents.append(
                    {
                        "incident_id": path.stem,
                        "state": "INVALID",
                        "error": type(exc).__name__,
                    }
                )
                continue

            if incident is None:
                continue

            incidents.append(
                {
                    "incident_id": incident.incident_id,
                    "state": incident.state,
                    "attempts": incident.attempts,
                    "cooldown_until_epoch": incident.cooldown_until_epoch,
                    "target_paths": list(incident.target_paths),
                    "production_touched": incident.production_touched,
                }
            )

    return {
        "schema": "edarsahub.worker-maintenance-summary.v1",
        "incident_count": len(incidents),
        "incidents": incidents,
        "production_touched": False,
    }

def _is_production_env() -> bool:
    env_name = (
        os.environ.get("EDARSA_ENV")
        or os.environ.get("APP_ENV")
        or os.environ.get("ENVIRONMENT")
        or "PREVIEW"
    ).upper()
    return "PROD" in env_name


def _read_autoconvergence_state() -> dict[str, Any]:
    try:
        data = json.loads(AUTOCONVERGENCE_STATE.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _write_autoconvergence_state(payload: dict[str, Any]) -> None:
    record = {
        "schema": "edarsahub.worker-autoconvergence-state.v1",
        **payload,
        "updated_at_utc": utc_now(),
        "production_touched": False,
    }
    atomic_json(AUTOCONVERGENCE_STATE, record)


def _compute_mcp_backend_tree_identity() -> str | None:
    components: list[str] = []
    for rel in MCP_BACKEND_IDENTITY_PATHS:
        proc = run(["git", "rev-parse", f"HEAD:{rel}"], timeout=20)
        sha = (proc.stdout or "").strip().lower()
        if proc.returncode != 0 or not re.fullmatch(r"[0-9a-f]{40}", sha):
            return None
        components.append(f"{rel}={sha}")
    return hashlib.sha256(("\n".join(components) + "\n").encode("utf-8")).hexdigest()


def _probe_local_backend_health() -> bool:
    proc = run(
        [
            "curl",
            "--silent",
            "--connect-timeout",
            "2",
            "--max-time",
            "5",
            "--output",
            "/dev/null",
            "--write-out",
            "%{http_code}",
            "http://127.0.0.1:8001/api/health",
        ],
        timeout=10,
    )
    code = (proc.stdout or "").strip()[-3:]
    return proc.returncode == 0 and len(code) == 3 and code.isdigit() and code[0] in {"2", "3", "4"}


def _supervisor_service_running(service: str) -> bool:
    proc = run(["supervisorctl", "status", service], timeout=15)
    return proc.returncode == 0 and "RUNNING" in (proc.stdout or "")


def _restart_service(service: str, reason: str) -> bool:
    if _is_production_env():
        audit("AUTOCONVERGENCE_RESTART_BLOCKED_PRODUCTION_ENV", service=service, reason=reason)
        return False
    res = run(["supervisorctl", "restart", service], timeout=60)
    ok = res.returncode == 0
    audit(
        "AUTOCONVERGENCE_SERVICE_RESTARTED",
        service=service,
        reason=reason,
        ok=ok,
        output=(res.stdout or "")[-800:],
    )
    return ok


def converge_runtime_permanently(
    *,
    ff: dict[str, Any],
    runtime: dict[str, Any],
) -> dict[str, Any]:
    """Permanent self-healing autoconvergence across Worker, Mirror, Backend, and MCP.

    Eliminates recurring runtime divergences after commits land on Edarsahub_Desarrollo
    without external intervention. Strictly fail-closed in Production, never force-pushes,
    and defers restarts while a job holds active execution ownership.
    """
    if _is_production_env():
        return {
            "schema": "edarsahub.worker-autoconvergence.v1",
            "status": "BLOCKED_PRODUCTION_ENV",
            "production_touched": False,
        }

    now_ts = epoch()
    state = _read_autoconvergence_state()
    state_changed = False
    actions: list[dict[str, Any]] = []

    branch = run(["git", "branch", "--show-current"], timeout=15).stdout.strip()
    local_head = run(["git", "rev-parse", "HEAD"], timeout=15).stdout.strip().lower()
    remote_head = run(["git", "rev-parse", f"{REMOTE}/{DEV_BRANCH}"], timeout=15).stdout.strip().lower()
    head_aligned = bool(
        branch == DEV_BRANCH
        and re.fullmatch(r"[0-9a-f]{40}", local_head)
        and local_head == remote_head
    )
    dirty_effective = ""
    try:
        dirty_effective = effective_git_status()
    except Exception:
        dirty_effective = "__STATUS_FAILED__"
    status_ok = dirty_effective != "__STATUS_FAILED__"
    clean_checkout = status_ok and dirty_effective == ""
    dirty_paths = _parse_porcelain_dirty_paths(dirty_effective) if (status_ok and dirty_effective) else set()
    worker_paths_clean = status_ok and (
        clean_checkout
        or (bool(dirty_paths) and not _dirty_paths_overlap_prefixes(dirty_paths, ("tools/mirror_sync",)))
    )
    mcp_backend_paths_clean = status_ok and (
        clean_checkout
        or (bool(dirty_paths) and not _dirty_paths_overlap_prefixes(dirty_paths, MCP_BACKEND_IDENTITY_PATHS))
    )

    # Determine if a mutation job is currently executing so we never disrupt in-flight work.
    current_job_id = str(runtime.get("current_job_id") or "").strip()
    job_active = False
    if current_job_id:
        ownership = active_execution_ownership(
            current_job_id,
            heartbeat_stale_seconds=PROCESSING_GRACE,
        )
        job_active = ownership.get("active") is True

    # 1. Worker code-tree autoconvergence (HEAD:tools/mirror_sync vs active_worker_code_tree_sha)
    expected_worker_tree = run(["git", "rev-parse", "HEAD:tools/mirror_sync"], timeout=15).stdout.strip().lower()
    active_worker_tree = read_text(RUNTIME / "active_worker_code_tree_sha").lower()
    worker_tree_aligned = bool(
        re.fullmatch(r"[0-9a-f]{40}", expected_worker_tree)
        and active_worker_tree == expected_worker_tree
    )
    worker_action = "ALIGNED"
    if not worker_tree_aligned and re.fullmatch(r"[0-9a-f]{40}", expected_worker_tree):
        last_worker_restart = float(state.get("last_worker_tree_restart_epoch") or 0.0)
        if not head_aligned or not worker_paths_clean:
            worker_action = "DEFERRED_NON_CANONICAL_CHECKOUT"
        elif job_active:
            worker_action = "DEFERRED_ACTIVE_JOB"
        elif (now_ts - last_worker_restart) < AUTOCONVERGENCE_WORKER_COOLDOWN_SECONDS:
            worker_action = "COOLDOWN"
        else:
            ok = request_universal_restart("WORKER_CODE_TREE_DRIFT_AUTOCONVERGENCE")
            state["last_worker_tree_restart_epoch"] = now_ts
            state["last_worker_tree_target"] = expected_worker_tree
            state_changed = True
            if ok:
                # Wait briefly for universal_job_worker.sh write_runtime_identity() ack
                deadline = time.time() + 10.0
                while time.time() < deadline:
                    time.sleep(0.5)
                    if read_text(RUNTIME / "active_worker_code_tree_sha").lower() == expected_worker_tree:
                        worker_tree_aligned = True
                        break
                worker_action = "RECOVERED_AUTO" if worker_tree_aligned else "RESTART_REQUESTED_PENDING_ACK"
            else:
                worker_action = "RESTART_FAILED"
            actions.append({
                "component": WORKER_SERVICE,
                "action": worker_action,
                "expected_tree": expected_worker_tree,
                "active_tree": read_text(RUNTIME / "active_worker_code_tree_sha").lower() or None,
            })

    # 2. Mirror fast-forward autoconvergence (strictly safe FF only when behind Development)
    mirror_action = "ALIGNED"
    mirror_aligned = False
    if head_aligned:
        mirror_branch = os.environ.get("EDARSAHUB_MIRROR_BRANCH", "mirror/emergent-live")
        run(["git", "fetch", "--quiet", REMOTE, mirror_branch], timeout=45)
        mirror_sha = run(["git", "rev-parse", f"{REMOTE}/{mirror_branch}"], timeout=15).stdout.strip().lower()
        mirror_aligned = mirror_sha == remote_head
        if not mirror_aligned and re.fullmatch(r"[0-9a-f]{40}", mirror_sha):
            mb = run(["git", "merge-base", mirror_sha, remote_head], timeout=15).stdout.strip().lower()
            writer_lock_exists = (STATE / "git-writer.lock.d").exists()
            last_mirror_attempt = float(state.get("last_mirror_ff_epoch") or 0.0)
            if mb != mirror_sha:
                mirror_action = "DEFERRED_NON_FF_MIRROR"
            elif writer_lock_exists or job_active:
                mirror_action = "DEFERRED_WRITER_BUSY"
            elif not status_ok:
                mirror_action = "DEFERRED_LOCAL_DIRTY"
            elif (now_ts - last_mirror_attempt) < AUTOCONVERGENCE_MIRROR_COOLDOWN_SECONDS:
                mirror_action = "COOLDOWN"
            else:
                state["last_mirror_ff_epoch"] = now_ts
                state_changed = True
                try:
                    try:
                        from tools.mirror_sync import git_divergence_guard as _gdg
                    except ModuleNotFoundError:
                        import git_divergence_guard as _gdg
                    if clean_checkout:
                        conv = _gdg.ensure_submit_convergence(
                            ROOT,
                            job_id="CONTROL-PLANE-AUTOCONVERGENCE",
                            owner="worker-control-plane",
                            owner_pid=os.getpid(),
                        )
                        if conv.get("converged") is True:
                            mirror_aligned = True
                            mirror_action = "MIRROR_FF_CONVERGED_AUTO"
                        else:
                            mirror_action = f"MIRROR_DEFERRED:{conv.get('status')}"
                    else:
                        tok = _gdg.acquire_writer_lock(
                            ROOT,
                            job_id="CONTROL-PLANE-AUTOCONVERGENCE",
                            owner="worker-control-plane",
                            owner_pid=os.getpid(),
                        )
                        try:
                            push = _gdg.authorized_push(
                                ROOT,
                                args=["push", REMOTE, f"{remote_head}:refs/heads/{mirror_branch}"],
                                job_id="CONTROL-PLANE-AUTOCONVERGENCE",
                                owner="worker-control-plane",
                            )
                            if push.returncode == 0:
                                run(["git", "fetch", "--quiet", REMOTE, mirror_branch], timeout=45)
                                post_mirror = run(
                                    ["git", "rev-parse", f"{REMOTE}/{mirror_branch}"],
                                    timeout=15,
                                ).stdout.strip().lower()
                                if post_mirror == remote_head:
                                    mirror_aligned = True
                                    mirror_action = "MIRROR_FF_CONVERGED_DISJOINT_DIRTY_AUTO"
                                else:
                                    mirror_action = "MIRROR_DEFERRED:POSTCHECK_MISMATCH"
                            else:
                                mirror_action = "MIRROR_DEFERRED:BLOCKED_PUSH_REJECTED"
                        finally:
                            _gdg.release_writer_lock(ROOT, tok)
                except Exception as exc:
                    mirror_action = f"MIRROR_ERROR:{type(exc).__name__}"
                actions.append({
                    "component": "mirror/emergent-live",
                    "action": mirror_action,
                    "development_sha": remote_head,
                })
    else:
        mirror_action = "DEFERRED_HEAD_NOT_ALIGNED"

    # 3. Backend + MCP code-tree autoconvergence (keeps capability catalog & cold-cache service aligned)
    expected_mcp_tree = _compute_mcp_backend_tree_identity()
    active_mcp_tree = read_text(ACTIVE_MCP_BACKEND_TREE).lower()
    mcp_backend_aligned = bool(expected_mcp_tree and active_mcp_tree == expected_mcp_tree)
    mcp_backend_action = "ALIGNED"
    if expected_mcp_tree and not mcp_backend_aligned:
        if not active_mcp_tree and head_aligned and mcp_backend_paths_clean:
            # First-time baseline bootstrap when services are already healthy on current HEAD
            if _probe_local_backend_health() and _supervisor_service_running(MCP_SERVICE):
                atomic_json_marker_tmp = ACTIVE_MCP_BACKEND_TREE.with_name(
                    f"active_mcp_backend_tree_sha.tmp.{os.getpid()}"
                )
                atomic_json_marker_tmp.write_text(expected_mcp_tree + "\n", encoding="utf-8")
                os.replace(atomic_json_marker_tmp, ACTIVE_MCP_BACKEND_TREE)
                mcp_backend_aligned = True
                mcp_backend_action = "BASELINE_RECORDED"
            else:
                mcp_backend_action = "DEFERRED_SERVICES_UNHEALTHY"
        elif not head_aligned or not mcp_backend_paths_clean:
            mcp_backend_action = "DEFERRED_NON_CANONICAL_CHECKOUT"
        elif job_active:
            mcp_backend_action = "DEFERRED_ACTIVE_JOB"
        elif (now_ts - float(state.get("last_mcp_backend_restart_epoch") or 0.0)) < AUTOCONVERGENCE_MCP_BACKEND_COOLDOWN_SECONDS:
            mcp_backend_action = "COOLDOWN"
        else:
            state["last_mcp_backend_restart_epoch"] = now_ts
            state_changed = True
            backend_ok = _restart_service(BACKEND_SERVICE, "MCP_BACKEND_CODE_TREE_DRIFT_AUTOCONVERGENCE")
            ready = False
            if backend_ok:
                deadline = time.time() + 65.0
                while time.time() < deadline:
                    if _probe_local_backend_health():
                        ready = True
                        break
                    time.sleep(1.5)
            mcp_ok = _restart_service(MCP_SERVICE, "MCP_BACKEND_CODE_TREE_DRIFT_AUTOCONVERGENCE") if ready else False
            if ready and mcp_ok:
                mcp_deadline = time.time() + 15.0
                mcp_running = False
                while time.time() < mcp_deadline:
                    if _supervisor_service_running(MCP_SERVICE):
                        mcp_running = True
                        break
                    time.sleep(1.0)
            else:
                mcp_running = False
            if ready and mcp_ok and mcp_running:
                tmp_marker = ACTIVE_MCP_BACKEND_TREE.with_name(
                    f"active_mcp_backend_tree_sha.tmp.{os.getpid()}"
                )
                tmp_marker.write_text(expected_mcp_tree + "\n", encoding="utf-8")
                os.replace(tmp_marker, ACTIVE_MCP_BACKEND_TREE)
                mcp_backend_aligned = True
                mcp_backend_action = "RECOVERED_AUTO"
            else:
                mcp_backend_action = "RESTART_INCOMPLETE"
            actions.append({
                "component": f"{BACKEND_SERVICE}+{MCP_SERVICE}",
                "action": mcp_backend_action,
                "backend_ready": ready,
                "mcp_restarted": mcp_ok,
            })

    if state_changed:
        try:
            _write_autoconvergence_state(state)
        except OSError:
            pass

    overall = bool(head_aligned and worker_tree_aligned and mirror_aligned and mcp_backend_aligned)
    return {
        "schema": "edarsahub.worker-autoconvergence.v1",
        "at_utc": utc_now(),
        "head_aligned": head_aligned,
        "clean_checkout": clean_checkout,
        "worker_code_tree_aligned": worker_tree_aligned,
        "worker_action": worker_action,
        "mirror_aligned": mirror_aligned,
        "mirror_action": mirror_action,
        "mcp_backend_tree_aligned": mcp_backend_aligned,
        "mcp_backend_action": mcp_backend_action,
        "overall_autoconverged": overall,
        "actions": actions,
        "production_touched": False,
    }


def _run_global_lifecycle_cycle(
    *,
    ff: dict[str, Any],
    runtime: dict[str, Any],
    claims: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    try:
        from tools.mirror_sync import worker_lifecycle_recovery as _lr
    except ModuleNotFoundError:
        import worker_lifecycle_recovery as _lr

    # Safely reconcile stale converged runtime-drift incidents & settled/abandoned orphan publisher branches
    try:
        converged_reconcile = _lr.reconcile_converged_runtime_incidents(state_root=STATE)
    except Exception as exc:
        converged_reconcile = {"error": type(exc).__name__, "superseded": []}

    try:
        pruned_branches = _lr.prune_settled_orphan_publisher_branches(
            repo_root=ROOT,
            state_root=STATE,
            claims_dir=AGENT_GUARD / "state" / "claims",
            max_prune_per_cycle=5,
        )
    except Exception as exc:
        pruned_branches = {"error": type(exc).__name__, "pruned": []}

    try:
        historical_reconciliation = _lr.reconcile_historical_queue_artifacts(
            repo_root=ROOT,
            state_root=STATE,
            claims_dir=AGENT_GUARD / "state" / "claims",
        )
    except Exception as exc:
        historical_reconciliation = {"error": type(exc).__name__, "production_touched": False}

    try:
        active_authorizations = _lr.list_active_gate_authorizations(state_root=STATE)
    except Exception:
        active_authorizations = []

    try:
        try:
            from tools.mirror_sync import worker_cross_domain_handoff as _handoff_mod
        except ModuleNotFoundError:
            import worker_cross_domain_handoff as _handoff_mod

        cross_domain_handoffs = _handoff_mod.reconcile_cross_domain_handoffs(
            state_root=STATE,
            repo_root=ROOT,
        )
    except Exception as exc:
        cross_domain_handoffs = {
            "schema": "edarsahub.cross-domain-handoff-reconcile.v1",
            "error": type(exc).__name__,
            "production_touched": False,
        }

    detection = _lr.scan_global_lifecycle_blockers(
        repo_root=ROOT,
        state_root=STATE,
        claims_dir=AGENT_GUARD / "state" / "claims",
        ff=ff,
        runtime=runtime,
        claims_summary=claims,
    )
    automation_state = load_repair_automation_state()
    recovery = _lr.advance_lifecycle_recovery(
        detection,
        repo_root=ROOT,
        state_root=STATE,
        claims_dir=AGENT_GUARD / "state" / "claims",
        automation_state=automation_state,
    )
    try:
        resumable_concurrency = _lr.scan_resumable_concurrency_blocked_objectives(
            repo_root=ROOT,
            state_root=STATE,
        )
    except Exception as exc:
        resumable_concurrency = [{"error": type(exc).__name__}]
    detection["resumable_concurrency_objectives"] = resumable_concurrency
    detection["active_gate_authorizations"] = [
        {
            "gate_id": a.get("gate_id"),
            "authorization_id": a.get("authorization_id"),
            "domains": (a.get("scope") or {}).get("domains") or [],
            "expires_at_utc": a.get("expires_at_utc"),
        }
        for a in active_authorizations
    ]
    recovery["converged_runtime_incidents_reconciled"] = converged_reconcile
    recovery["orphan_publisher_branches_pruned"] = pruned_branches
    recovery["historical_reconciliation"] = {
        "schema": historical_reconciliation.get("schema"),
        "pending_audit_reconciled_count": historical_reconciliation.get("pending_audit_reconciled_count", 0),
        "historical_drafts_classified_count": historical_reconciliation.get("historical_drafts_classified_count", 0),
        "abandoned_branches_pruned_count": historical_reconciliation.get("abandoned_branches_pruned_count", 0),
        "ledger_path": historical_reconciliation.get("ledger_path"),
        "production_touched": False,
    }
    recovery["cross_domain_handoffs"] = cross_domain_handoffs
    return detection, recovery


def cycle() -> dict[str, Any]:
    ff = preserve_and_fast_forward()
    runtime = heal_runtime_generation_and_heartbeat()
    try:
        autoconvergence = converge_runtime_permanently(ff=ff, runtime=runtime)
    except Exception as exc:
        audit("AUTOCONVERGENCE_CYCLE_EXCEPTION", error=str(exc))
        autoconvergence = {
            "schema": "edarsahub.worker-autoconvergence.v1",
            "status": "ERROR_FAIL_CLOSED",
            "error": type(exc).__name__,
            "production_touched": False,
        }
    claims = reconcile_agent_guard_orphans()
    try:
        try:
            from tools.mirror_sync import agent_guard_telemetry as _ag_tel
        except ModuleNotFoundError:
            import agent_guard_telemetry as _ag_tel
        agent_guard_supervision = _ag_tel.collect_agent_guard_supervision(
            repo_root=ROOT,
            state_root=STATE,
        )
    except Exception as exc:
        audit("AGENT_GUARD_SUPERVISION_EXCEPTION", error=str(exc))
        agent_guard_supervision = {
            "schema": "edarsahub.agent-guard-telemetry.v1",
            "health": "UNAVAILABLE",
            "supervision_mode": "CONTROL_PLANE_INDEPENDENT",
            "vscode_dependency": False,
            "error": type(exc).__name__,
            "production_touched": False,
        }
    requeued = requeue_stale_processing()
    automatic_repair = automatic_repair_orchestration()
    automatic_repair_execution = advance_repair_automation(
        automatic_repair
    )
    try:
        lifecycle_detection, lifecycle_recovery = _run_global_lifecycle_cycle(
            ff=ff,
            runtime=runtime,
            claims=claims,
        )
    except Exception as exc:
        audit("LIFECYCLE_CYCLE_EXCEPTION", error=str(exc))
        lifecycle_detection = {"schema": "edarsahub.worker-lifecycle-detection.v1", "error": type(exc).__name__, "production_touched": False}
        lifecycle_recovery = {"schema": "edarsahub.worker-lifecycle-recovery.v1", "status": "ERROR_FAIL_CLOSED", "production_touched": False}
    payload = {
        "schema": "edarsahub.worker-control-plane.v1",
        "at_utc": utc_now(),
        "ff": ff,
        "runtime": runtime,
        "autoconvergence": autoconvergence,
        "agent_guard": claims,
        "agent_guard_supervision": agent_guard_supervision,
        "stale_processing_requeued": requeued,
        "maintenance": maintenance_runtime_summary(),
        "automatic_repair": automatic_repair,
        "automatic_repair_execution": automatic_repair_execution,
        "lifecycle_detection": lifecycle_detection,
        "lifecycle_recovery": lifecycle_recovery,
        "production_touched": False,
    }
    atomic_json(STATUS, payload)
    return payload


def main() -> int:
    once = "--once" in os.sys.argv

    try:
        active_runtime = (
            write_control_plane_runtime_marker()
        )
        audit(
            "CONTROL_PLANE_RUNTIME_ACTIVE",
            active_identity=active_runtime[
                "active_identity"
            ],
            development_sha=active_runtime[
                "development_sha"
            ],
            pid=active_runtime["pid"],
        )
    except Exception as exc:
        audit(
            "CONTROL_PLANE_RUNTIME_IDENTITY_FAILED",
            error=str(exc),
        )

    while True:
        try:
            payload = cycle()
            print("CONTROL_PLANE_STATE=" + json.dumps(payload, ensure_ascii=False, sort_keys=True), flush=True)
        except Exception as exc:
            audit("CONTROL_PLANE_CYCLE_EXCEPTION", error=str(exc))
            print(f"CONTROL_PLANE_ERROR={exc}", flush=True)
        if once:
            return 0
        time.sleep(max(5, INTERVAL))


if __name__ == "__main__":
    raise SystemExit(main())
